using System.Collections; using UnityEngine; namespace Reflectable { public sealed class PlayerCharacterPresenter:MonoBehaviour { [SerializeField] CharacterDatabase database; [SerializeField] Transform characterSlot; GameObject current; public void Configure(CharacterDatabase value,Transform slot){database=value;characterSlot=slot;} public void Present(string id){var data=database?database.Find(id):null;if(!data)data=database?database.Default:null;if(!data||!data.prefab||!characterSlot)return;if(current)Destroy(current);current=Instantiate(data.prefab,characterSlot);current.name=data.displayName+" Visual";current.transform.localPosition=Vector3.zero;current.transform.localRotation=Quaternion.identity;} } }
